import iziToast from 'izitoast';
import 'izitoast/dist/css/iziToast.min.css';
import { getImagesByQuery } from './js/pixabay-api';
import {
  clearGallery,
  createGallery,
  hideLoader,
  showLoader,
} from './js/render-functions';

const inputElem = document.querySelector('input[name="search-text"]');
const form = document.querySelector('form');
form.addEventListener('submit', e => {
  e.preventDefault();
  showLoader();
  clearGallery();
  if (inputElem.value.toLowerCase().trim() === '') {
    return iziToast.error({
      message: 'Sorry, input is empty!',
      position: 'topRight',
      backgroundColor: ' #ef4040;',
    });
  } else {
    getImagesByQuery(
      inputElem.value.toLowerCase().trim()
      //if don't error
    )
      .then(hits => {
        if (hits.length === 0) {
          return iziToast.error({
            message:
              'Sorry, there are no images matching your search query. Please try again!',
            position: 'topRight',
            backgroundColor: ' #ef4040;',
          });
        } else {
          // hideLoader();
          return createGallery(hits);
          // lightbox.refresh();}
        }
      })
      .catch(error => {
        return iziToast.error({
          message: `Sorry, here ${error}!`,
          position: 'topRight',
          backgroundColor: ' #ef4040;',
        });
      })
      .finally(() => {
        hideLoader();
      });
  }
});
